CREATE TABLE IF NOT EXISTS bookings.recurring_payment_schedule (
    id                UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id         INT         NOT NULL,
    recurring_rule_id UUID        NOT NULL REFERENCES bookings.recurring_rules(id) ON DELETE CASCADE,
    customer_id       UUID        NOT NULL REFERENCES bookings.customers(id),
    period_start      DATE        NOT NULL,
    period_end        DATE        NOT NULL,
    amount_due        NUMERIC(10,2) NOT NULL DEFAULT 0,
    due_date          DATE        NOT NULL,
    status            TEXT        NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'paid', 'overridden', 'cancelled')),
    override_by       TEXT,
    override_note     TEXT,
    paid_at           TIMESTAMPTZ,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (recurring_rule_id, period_start)
);
CREATE INDEX IF NOT EXISTS idx_rps_tenant   ON bookings.recurring_payment_schedule(tenant_id);
CREATE INDEX IF NOT EXISTS idx_rps_rule     ON bookings.recurring_payment_schedule(recurring_rule_id);
CREATE INDEX IF NOT EXISTS idx_rps_status   ON bookings.recurring_payment_schedule(tenant_id, status);
CREATE INDEX IF NOT EXISTS idx_rps_due_date ON bookings.recurring_payment_schedule(due_date, status) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS idx_rps_customer ON bookings.recurring_payment_schedule(customer_id);
